"""depth_ok vs a straightforward character loop on random text."""
import random, sys
sys.path.insert(0, '/workspace/tests')
import importlib.util
spec = importlib.util.spec_from_file_location('m', '/workspace/submission/main.py')
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)

def simple(text):
    depth = 0
    in_string = False
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if in_string:
            if c == '\\':
                i += 2
                continue
            if c == '"':
                in_string = False
        else:
            if c == '"':
                in_string = True
            elif c in '{[':
                depth += 1
                if depth > 64:
                    return False
            elif c in '}]':
                if depth:
                    depth -= 1
        i += 1
    return True

rng = random.Random(77)
alphabet = list('{}[]"' + '\\') + ['a', 'b', '{', '}', 'n', 'u', '0', ' ', '\t']
bad = 0
for trial in range(40000):
    n = rng.randint(0, 40)
    text = ''.join(rng.choice(alphabet) for _ in range(n))
    a = m.depth_ok(text)
    b = simple(text)
    if a != b:
        bad += 1
        print('MISMATCH', repr(text), a, b)
        if bad > 5:
            break
# structured JSON-ish samples
for trial in range(20000):
    n = rng.randint(1, 30)
    parts = []
    for _ in range(n):
        r = rng.random()
        if r < 0.3:
            parts.append(rng.choice(['{', '[', '}', ']']))
        elif r < 0.5:
            parts.append('"' + ''.join(rng.choice(['a', '\\\\"', '\\\\n', '\\\\u007b', '{', '}']) for _ in range(rng.randint(0, 3))) + '"')
        elif r < 0.6:
            parts.append(rng.choice(['\\\\"', '\\\\{', '\\\\}']))
        else:
            parts.append(rng.choice([',', ':', '1', ' ']))
    text = ''.join(parts)
    a = m.depth_ok(text)
    b = simple(text)
    if a != b:
        bad += 1
        print('MISMATCH2', repr(text), a, b)
        if bad > 5:
            break
print('depth scan differential done, failures', bad)
